import {
	GetModulesCreatedForProjectGroupDocument,
	type GetModulesCreatedForProjectGroupSubscription,
	type GetModulesCreatedForProjectGroupSubscriptionVariables,
	GetModulesDeletedForProjectGroupDocument,
	type GetModulesDeletedForProjectGroupSubscription,
	type GetModulesDeletedForProjectGroupSubscriptionVariables,
	ProjectGroupRevisionsFinishedDocument,
	type ProjectGroupRevisionsFinishedSubscription,
	type ProjectGroupRevisionsFinishedSubscriptionVariables,
	useFilesForProjectGroupQuery
} from '@/generated/graphql'
import { noop } from 'lodash'
import { useEffect, useMemo } from 'react'

/**
 * Map from file path to project id
 */
export const useProjectGroupFileMap = () => {
	const id = process.env.EXPO_PUBLIC_PROJECT_GROUP_ID
	const isFileBased = true
	const { data, loading, refetch, subscribeToMore } =
		useFilesForProjectGroupQuery({
			variables: {
				id
			}
		})

	useEffect(() => {
		if (!isFileBased || !id) {
			return noop
		}

		const unsubscribeRevisionsFinished = subscribeToMore<
			ProjectGroupRevisionsFinishedSubscription,
			ProjectGroupRevisionsFinishedSubscriptionVariables
		>({
			document: ProjectGroupRevisionsFinishedDocument,
			variables: { id },
			updateQuery: (prev, { subscriptionData }) => {
				if (
					!subscriptionData?.data?.projectGroupRevisionsFinished ||
					subscriptionData.data.projectGroupRevisionsFinished.id !== id
				) {
					return prev
				}
				refetch()
				return prev
			}
		})

		const unsubscribeModulesCreated = subscribeToMore<
			GetModulesCreatedForProjectGroupSubscription,
			GetModulesCreatedForProjectGroupSubscriptionVariables
		>({
			document: GetModulesCreatedForProjectGroupDocument,
			variables: { id },
			updateQuery: (prev, { subscriptionData }) => {
				if (
					!subscriptionData?.data?.projectGroupModulesCreated ||
					subscriptionData.data.projectGroupModulesCreated.id !== id
				) {
					return prev
				}
				refetch()
				return prev
			}
		})

		const unsubscribeModulesDeleted = subscribeToMore<
			GetModulesDeletedForProjectGroupSubscription,
			GetModulesDeletedForProjectGroupSubscriptionVariables
		>({
			document: GetModulesDeletedForProjectGroupDocument,
			variables: { id },
			updateQuery: (prev, { subscriptionData }) => {
				if (
					!subscriptionData?.data?.projectGroupModulesDeleted ||
					subscriptionData.data.projectGroupModulesDeleted.id !== id
				) {
					return prev
				}
				refetch()
				return prev
			}
		})

		return () => {
			unsubscribeRevisionsFinished()
			unsubscribeModulesCreated()
			unsubscribeModulesDeleted()
		}
	}, [id, isFileBased, refetch, subscribeToMore])

	const fileMap = useMemo(() => {
		return (
			data?.projectGroupById?.files?.reduce((acc, file) => {
				const path = file.latestRevision?.filePath
				if (path) {
					acc[path] = file.id
				}
				return acc
			}, {} as Record<string, string>) ?? {}
		)
	}, [data])
	const fs = useMemo(() => {
		return (
			data?.projectGroupById?.projectFiles?.reduce((acc, file) => {
				const path = file.path
				if (path) {
					acc[path] = file.content
				}
				return acc
			}, {} as Record<string, string>) ?? {}
		)
	}, [data?.projectGroupById?.projectFiles])

	return {
		/**
		 * A map from file path to file content.
		 */
		fs,
		/**
		 * A map from file path to project id.
		 */
		fileMap,
		/**
		 * A map from project id to file path.
		 */
		reverseMap: useMemo(() => {
			return Object.entries(fileMap).reduce((acc, [path, projectId]) => {
				acc[projectId] = path
				return acc
			}, {} as Record<string, string>)
		}, [fileMap]),
		loading
	}
}
